CREATE TABLE schema_migrations (name text PRIMARY KEY, applied_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE roles (name text PRIMARY KEY);
CREATE TABLE permissions (name text PRIMARY KEY);
CREATE TABLE role_permissions (role text REFERENCES roles, permission text REFERENCES permissions, PRIMARY KEY(role,permission));
CREATE TABLE users (id uuid PRIMARY KEY, email text UNIQUE NOT NULL, password_hash text NOT NULL, region_id uuid, facility_id uuid, active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE user_roles (user_id uuid REFERENCES users, role text REFERENCES roles, PRIMARY KEY(user_id,role));
CREATE TABLE sessions (token_hash text PRIMARY KEY, user_id uuid NOT NULL REFERENCES users, csrf text NOT NULL, expires_at timestamptz NOT NULL);
CREATE TABLE regions (id uuid PRIMARY KEY, name text UNIQUE NOT NULL);
CREATE TABLE facilities (id uuid PRIMARY KEY, region_id uuid NOT NULL REFERENCES regions, name text NOT NULL);
CREATE TABLE production_plants (id uuid PRIMARY KEY, facility_id uuid NOT NULL REFERENCES facilities, name text NOT NULL);
ALTER TABLE users ADD FOREIGN KEY(region_id) REFERENCES regions;
ALTER TABLE users ADD FOREIGN KEY(facility_id) REFERENCES facilities;
CREATE TABLE installation_points (id uuid PRIMARY KEY, facility_id uuid NOT NULL REFERENCES facilities, plant_id uuid REFERENCES production_plants, name text NOT NULL, station text, pipeline text, classification text NOT NULL, latitude numeric CHECK(latitude BETWEEN -90 AND 90), longitude numeric CHECK(longitude BETWEEN -180 AND 180), upstream_id uuid REFERENCES installation_points);
CREATE SEQUENCE meter_number;
CREATE TABLE meters (id text PRIMARY KEY DEFAULT ('GWL-PM-' || lpad(nextval('meter_number')::text,6,'0')), serial_number text, manufacturer text, model text, meter_type text, diameter numeric, technology text, firmware text, status text NOT NULL DEFAULT 'Active' CHECK(status IN ('Active','Inactive','Offline','Faulty','Removed','Replaced','Under Maintenance')), expected_minutes integer NOT NULL DEFAULT 60 CHECK(expected_minutes>0), offline_minutes integer NOT NULL DEFAULT 180 CHECK(offline_minutes>expected_minutes), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE communication_devices (id uuid PRIMARY KEY, meter_id text REFERENCES meters, technology text, device_id text, logger_id text, communication_id text, imei text, sim_identifier text, gateway_id text, vendor_platform_id text);
CREATE TABLE meter_identifiers (id uuid PRIMARY KEY, meter_id text NOT NULL REFERENCES meters, namespace text NOT NULL, kind text NOT NULL, value text NOT NULL, normalized text NOT NULL, verified_at timestamptz NOT NULL DEFAULT now(), UNIQUE(namespace,kind,normalized,meter_id));
CREATE INDEX identity_lookup ON meter_identifiers(namespace,kind,normalized);
CREATE TABLE meter_installations (id uuid PRIMARY KEY, meter_id text NOT NULL REFERENCES meters, point_id uuid NOT NULL REFERENCES installation_points, installed_at timestamptz NOT NULL, removed_at timestamptz, commissioned_at timestamptz, CHECK(removed_at IS NULL OR removed_at>installed_at));
CREATE UNIQUE INDEX one_active_meter ON meter_installations(meter_id) WHERE removed_at IS NULL;
CREATE UNIQUE INDEX one_active_point ON meter_installations(point_id) WHERE removed_at IS NULL;
CREATE TABLE parser_configurations (id uuid PRIMARY KEY, name text NOT NULL, format text NOT NULL CHECK(format IN ('json','csv','xlsx','xml','txt','html')), namespace text NOT NULL, record_path text NOT NULL DEFAULT '', enabled boolean NOT NULL DEFAULT false);
CREATE TABLE field_mappings (id uuid PRIMARY KEY, parser_id uuid NOT NULL REFERENCES parser_configurations, source text NOT NULL, target text NOT NULL, UNIQUE(parser_id,source));
CREATE TABLE email_sources (id uuid PRIMARY KEY, name text NOT NULL, sender text, domain text, subject_contains text, label text, keyword text, filename_contains text, attachment_type text, vendor_identifier text, parser_id uuid NOT NULL REFERENCES parser_configurations, enabled boolean NOT NULL DEFAULT false, CHECK(sender IS NOT NULL OR domain IS NOT NULL));
CREATE TABLE email_messages (id text PRIMARY KEY, thread_id text NOT NULL, sender text, recipient text, subject text, received_at timestamptz NOT NULL, processed_at timestamptz, parser_id uuid REFERENCES parser_configurations, status text NOT NULL DEFAULT 'Pending', raw_payload jsonb NOT NULL, error text, retry_count integer NOT NULL DEFAULT 0);
CREATE INDEX messages_time ON email_messages(received_at DESC);
CREATE TABLE email_attachments (id uuid PRIMARY KEY, message_id text NOT NULL REFERENCES email_messages, filename text NOT NULL, mime_type text NOT NULL, checksum text NOT NULL, payload bytea NOT NULL, UNIQUE(message_id,checksum,filename));
CREATE TABLE email_processing_logs (id uuid PRIMARY KEY, message_id text NOT NULL REFERENCES email_messages, action text NOT NULL, detail text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE unidentified_meters (id uuid PRIMARY KEY, namespace text NOT NULL, kind text NOT NULL, detected_id text NOT NULL, first_seen timestamptz NOT NULL, last_seen timestamptz NOT NULL, status text NOT NULL DEFAULT 'Review', meter_id text REFERENCES meters, sample jsonb NOT NULL, UNIQUE(namespace,kind,detected_id));
CREATE TABLE discovered_transmissions (discovery_id uuid REFERENCES unidentified_meters, message_id text REFERENCES email_messages, PRIMARY KEY(discovery_id,message_id));
CREATE TABLE identity_matches (id uuid PRIMARY KEY, discovery_id uuid REFERENCES unidentified_meters, meter_id text REFERENCES meters, decision text NOT NULL, user_id uuid REFERENCES users, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE meter_readings (id uuid PRIMARY KEY, meter_id text NOT NULL REFERENCES meters, installation_id uuid REFERENCES meter_installations, point_id uuid REFERENCES installation_points, reading_at timestamptz NOT NULL, received_at timestamptz NOT NULL, original_timestamp text NOT NULL, original_timezone text, sequence text NOT NULL DEFAULT '', cumulative_volume numeric, flow_rate numeric, forward_volume numeric, reverse_volume numeric, pressure numeric, temperature numeric, battery numeric, signal_strength numeric, device_status text, alarm_codes text, error_codes text, communication_status text, unit text, source_message_id text NOT NULL REFERENCES email_messages, parser_id uuid REFERENCES parser_configurations, quality text NOT NULL, raw_value jsonb NOT NULL, UNIQUE(meter_id,reading_at,sequence));
CREATE INDEX readings_meter_time ON meter_readings(meter_id,reading_at DESC);
CREATE INDEX readings_time ON meter_readings(reading_at DESC);
CREATE TABLE meter_alarms (id uuid PRIMARY KEY, meter_id text NOT NULL REFERENCES meters, reading_id uuid REFERENCES meter_readings, code text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE data_quality_events (id uuid PRIMARY KEY, meter_id text REFERENCES meters, message_id text REFERENCES email_messages, reading_id uuid REFERENCES meter_readings, code text NOT NULL, severity text NOT NULL, detail text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE duplicate_events (id uuid PRIMARY KEY, message_id text REFERENCES email_messages, detail text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE audit_logs (id uuid PRIMARY KEY, user_id uuid REFERENCES users, action text NOT NULL, entity_id text, previous_value jsonb, new_value jsonb, ip text, created_at timestamptz NOT NULL DEFAULT now());
CREATE FUNCTION deny_audit_mutation() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'Audit logs are immutable'; END; $$;
CREATE TRIGGER immutable_audit BEFORE UPDATE OR DELETE ON audit_logs FOR EACH ROW EXECUTE FUNCTION deny_audit_mutation();
CREATE TABLE integration_secrets (name text PRIMARY KEY, encrypted_value text NOT NULL);
CREATE TABLE system_settings (name text PRIMARY KEY, value jsonb NOT NULL);
INSERT INTO system_settings VALUES ('sync','{"last_success":null,"last_error":null,"running":false}'::jsonb);
CREATE TABLE notifications (id uuid PRIMARY KEY, meter_id text REFERENCES meters, kind text NOT NULL, detail text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
